package com.minewaku.chatter.identityaccess.user.internal.model; import java.time.*; public record Birthday(LocalDate value) { public Birthday { if(value==null) throw new IllegalArgumentException("Birthday is required"); LocalDate t=LocalDate.now(); if(value.isAfter(t)||Period.between(value,t).getYears()>150) throw new IllegalArgumentException("Invalid birthday"); } public int age(){return Period.between(value,LocalDate.now()).getYears();} }